# runs.py RUN_DIR: each Bash call that runs a build, a suite, a stage, the demos, the spec build or the model check
d=sys.argv[1]
PATS=[('compileAll',r'\bant\b[^;&|\n]*\bcompileAll\b'),('testQuick',r'\bant\b[^;&|\n]*\btestQuick\b'),('testFast',r'\bant\b[^;&|\n]*\btestFast\b'),
 ('testSystem',r'\bant\b[^;&|\n]*\btestSystem\b'),('testSpecData',r'\bant\b[^;&|\n]*\btestSpecData\b'),('count',r'checker-count/run\.sh\s+\S+\s+\S+'),
